using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.ARC.TiposArchivo;using GraphApi.Services.ARC.TiposArchivo;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.ARC.TiposArchivo{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de TiposArchivos: creación, actualización y eliminación.")]    public class TiposArchivoMutation    {        [Authorize]        [GraphQLName("createTiposArchivo")]        [GraphQLDescription("Crea un nuevo TiposArchivo usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadTiposArchivo> CreateTiposArchivoAsync(            [GraphQLDescription("Datos necesarios para crear el TiposArchivo.")]            clCreateTiposArchivo objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposArchivo.")]            ITiposArchivoService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateTiposArchivo(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateTiposArchivo")]        [GraphQLDescription("Actualiza los campos especificados de un TiposArchivo existente.")]        public async Task<clReadTiposArchivo?> UpdateTiposArchivoAsync(            [GraphQLDescription("Datos del TiposArchivo a actualizar.")]            clUpdateTiposArchivo objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposArchivo.")]            ITiposArchivoService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateTiposArchivo(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteTiposArchivo")]        [GraphQLDescription("Elimina un TiposArchivo por su ID.")]        public async Task<bool> delTiposArchivoAsync(            [GraphQLDescription("ID del TiposArchivo a eliminar.")]            int nTiposArchivoID,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposArchivo.")]            ITiposArchivoService objService        )        {            return await objService.DeleteTiposArchivo(nTiposArchivoID);        }    }}